// Generated SDK declarations come from the same OpenAPI document the CLI reads.
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
const source = new URL("./openapi.generated.json", import.meta.url);
const target = new URL("./openapi.generated.d.ts", import.meta.url);
const unformatted =
  "/* oxlint-disable max-lines, typescript/no-redundant-type-constituents */\n// Generated by generate-client.mjs from openapi.generated.json. Do not edit.\n" +
  astToString(await openapiTS(source));
const output = execFileSync(
  fileURLToPath(new URL("../../../node_modules/.bin/oxfmt", import.meta.url)),
  ["--stdin-filepath", fileURLToPath(target)],
  { input: unformatted, encoding: "utf8" },
);
if (process.argv.includes("--check")) {
  if (readFileSync(target, "utf8") !== output) {
    throw new Error("Generated SDK types drifted; run adminbot:api:generate");
  }
} else {
  writeFileSync(target, output);
}
